create type public.user_role as enum ('client','advocate','admin');
create table public.profiles (id uuid primary key references auth.users on delete cascade,name text not null,email text not null,role public.user_role not null default 'client',phone text,created_at timestamptz default now());
create table public.advocates (id uuid primary key references public.profiles on delete cascade,name text not null,specializations text[] not null default '{}',experience_years int not null default 0,consultation_fee int not null default 0,city text not null,state text not null,verification_status text not null default 'pending' check(verification_status in('pending','verified','rejected')),available_for_consultation boolean not null default false,latitude numeric,longitude numeric);
create table public.availability (advocate_id uuid primary key references public.advocates on delete cascade,weekly jsonb not null default '{}',slot_duration int not null default 30);
create table public.documents (id uuid primary key,owner_id uuid not null references public.profiles on delete cascade,file_name text not null,storage_path text not null unique,file_type text not null check(file_type='application/pdf'),file_size bigint not null,shared_with uuid[] not null default '{}',created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.advocates enable row level security; alter table public.availability enable row level security; alter table public.documents enable row level security;
create policy "profile self" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id and role in ('client','advocate'));
create policy "advocates readable" on public.advocates for select using(auth.uid() is not null); create policy "advocate self" on public.advocates for update using(auth.uid()=id) with check(auth.uid()=id and verification_status=(select verification_status from public.advocates where id=auth.uid()));
create policy "availability readable" on public.availability for select using(auth.uid() is not null); create policy "availability owner" on public.availability for all using(auth.uid()=advocate_id) with check(auth.uid()=advocate_id);
create policy "documents authorized" on public.documents for select using(auth.uid()=owner_id or auth.uid()=any(shared_with)); create policy "documents owner" on public.documents for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
insert into storage.buckets(id,name,public) values('documents','documents',false);
create policy "document storage access" on storage.objects for all using(bucket_id='documents' and split_part(name,'/',1)=auth.uid()::text) with check(bucket_id='documents' and split_part(name,'/',1)=auth.uid()::text);
